@test
def test_noncentral_inverse():
    assert abs(sp.chndtr(3.0, sp.chndtridf(3.0, 0.5, 0.3), 0.3) - 0.5) < 1e-10
    assert abs(sp.chndtr(3.0, 2.0, sp.chndtrinc(3.0, 2.0, 0.3)) - 0.3) < 1e-10
    assert abs(sp.nctdtr(sp.nctdtridf(0.5, 1.0, 2.0), 1.0, 2.0) - 0.5) < 1e-9
    assert abs(sp.nctdtr(3.0, sp.nctdtrinc(3.0, 0.5, 2.0), 2.0) - 0.5) < 1e-9
    assert abs(sp.ncfdtr(3.0, sp.ncfdtridfd(3.0, 0.5, 1.0, 2.0), 1.0, 2.0) - 0.5) < 1e-9
    assert abs(sp.ncfdtr(3.0, 4.0, sp.ncfdtrinc(3.0, 4.0, 0.5, 2.0), 2.0) - 0.5) < 1e-9
    assert closec(np.array([sp.chndtridf(3.0, 0.5, 0.3), sp.chndtrinc(3.0, 2.0, 0.3), sp.nctdtridf(0.5, 1.0, 2.0), sp.nctdtrinc(3.0, 0.5, 2.0)]), [3.3898521137015365, 3.8777085021661755, 0.43736273153530536, 1.8181645676966673], 1e-4)

